#pragma once
#include "TabletTypes.h"
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <optional>
#include <vector>
namespace TabletHelper {
struct BenchNode { uintptr_t address=0; int parent=-1; std::string name,text; float x=0,y=0,w=0,h=0; float CenterX()const{return x+w/2;} float CenterY()const{return y+h/2;} };
struct BenchTargets { BenchNode panel,button,output; };
inline bool SameUiPoint(const BenchNode&a,const BenchNode&b){return std::abs(a.CenterX()-b.CenterX())<=12&&std::abs(a.CenterY()-b.CenterY())<=12;}
inline bool UiInsideExpanded(const BenchNode&a,const BenchNode&b,float m){return b.x>=a.x-m&&b.y>=a.y-m&&b.x+b.w<=a.x+a.w+m&&b.y+b.h<=a.y+a.h+m;}
inline bool Descendant(const std::vector<BenchNode>&n,size_t c,size_t p){for(size_t i=0;i<n.size()&&c<n.size();++i){if(c==p)return true;if(n[c].parent<0)return false;c=(size_t)n[c].parent;}return false;}
inline std::optional<size_t> LowestCommonAncestor(const std::vector<BenchNode>&n,size_t a,size_t b){std::vector<size_t> v;for(size_t i=0;i<n.size()&&a<n.size();++i){v.push_back(a);if(n[a].parent<0)break;a=(size_t)n[a].parent;}for(size_t i=0;i<n.size()&&b<n.size();++i){if(std::find(v.begin(),v.end(),b)!=v.end())return b;if(n[b].parent<0)break;b=(size_t)n[b].parent;}return std::nullopt;}
// Find the output above the middle of three equally sized live input slots.
inline std::optional<BenchNode> StructuralBenchOutput(const std::vector<BenchNode>&raw,const BenchNode&button){std::vector<BenchNode>s;for(const auto&n:raw){if(n.w<28||n.w>240||n.h<28||n.h>320||n.w/n.h<.4f||n.w/n.h>1.2f||n.y+n.h>=button.CenterY())continue;auto i=std::find_if(s.begin(),s.end(),[&](const auto&o){return SameUiPoint(o,n);});if(i==s.end())s.push_back(n);else if(n.w*n.h>i->w*i->h)*i=n;}auto sim=[](const BenchNode&a,const BenchNode&b){return std::abs(a.w-b.w)<=a.w*.2f&&std::abs(a.h-b.h)<=a.h*.2f;};std::optional<BenchNode> found;for(const auto&l:s)for(const auto&m:s)for(const auto&r:s){if(!(l.CenterX()<m.CenterX()&&m.CenterX()<r.CenterX())||!sim(l,m)||!sim(m,r)||std::abs(l.CenterY()-m.CenterY())>10||std::abs(r.CenterY()-m.CenterY())>10)continue;float g1=m.CenterX()-l.CenterX(),g2=r.CenterX()-m.CenterX();if(g1<m.w*.9f||g1>m.w*1.8f||std::abs(g1-g2)>m.w*.15f)continue;for(const auto&o:s){if(!sim(o,m)||o.y+o.h>=m.y||std::abs(o.CenterX()-m.CenterX())>m.w*.3f||std::abs(button.CenterX()-m.CenterX())>m.w*.4f)continue;if(found&&!SameUiPoint(*found,o))return std::nullopt;found=o;}}return found;}
// Anchor the real bench title and button. The button is 31 px below the clipped body.
inline std::optional<BenchTargets> DiscoverBench(const std::vector<BenchNode>&n,float width,float height){std::optional<BenchTargets>found;for(size_t b=0;b<n.size();++b){if(NormalizeIdentifier(n[b].text)!="reforge")continue;std::vector<size_t>panels;for(size_t t=0;t<n.size();++t)if(NormalizeIdentifier(n[t].text)=="reforgingbench"){auto a=LowestCommonAncestor(n,t,b);if(a&&std::find(panels.begin(),panels.end(),*a)==panels.end())panels.push_back(*a);}for(size_t p=b,steps=0;p<n.size()&&steps++<n.size();){auto id=ToLowerCopy(n[p].name+" "+n[p].text);if(ContainsCI(id,"reforg")&&(ContainsCI(id,"panel")||ContainsCI(id,"bench")||ContainsCI(id,"window"))&&std::find(panels.begin(),panels.end(),p)==panels.end())panels.push_back(p);if(n[p].parent<0)break;p=(size_t)n[p].parent;}for(auto p:panels){const auto&panel=n[p];const auto&button=n[b];if(panel.w<200||panel.h<200||panel.x<0||panel.y<0||panel.x+panel.w>width+1||panel.y+panel.h>height+1||panel.w*panel.h>=width*height*.8f||!UiInsideExpanded(panel,button,64)||button.w<35||button.w>500||button.h<10||button.h>150)continue;std::vector<BenchNode>d,o;for(size_t i=0;i<n.size();++i){if(i==p||!Descendant(n,i,p)||!UiInsideExpanded(panel,n[i],64)||n[i].w<10||n[i].h<10)continue;d.push_back(n[i]);auto name=ToLowerCopy(n[i].name);if((ContainsCI(name,"result")||ContainsCI(name,"output"))&&n[i].w<=200&&n[i].h<=200)o.push_back(n[i]);}std::optional<BenchNode>out;if(o.empty())out=StructuralBenchOutput(d,button);else if(o.size()==1)out=o.front();if(!out||SameUiPoint(button,*out))continue;BenchTargets c{panel,button,*out};if(found&&(!SameUiPoint(found->button,c.button)||!SameUiPoint(found->output,c.output)))return std::nullopt;found=c;}}return found;}
} // namespace TabletHelper
